const r=$input.first()?.json??{};
if(r.code!==0&&r.code!=='0')throw new Error('ABNORMAL_ORDER_COMMAND_EXIT_FAILED');
let value;try{const lines=String(r.stdout??'').split(/\r?\n/).filter(s=>s.trim().startsWith('{'));value=JSON.parse(lines.at(-1)??'');}catch{throw new Error('ABNORMAL_ORDER_RESULT_INVALID');}
if(value.status!=='SUCCESS'||!/^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value.runId)||!Array.isArray(value.sources)||value.sources.length!==3)throw new Error('ABNORMAL_ORDER_RESULT_FAILED');
for(const source of ['e10-main','tplus-kainan','tplus-kejia']){const rows=value.sources.filter(s=>s.source===source);if(rows.length!==1||rows[0].status!=='SUCCESS'||!Number.isSafeInteger(rows[0].read)||rows[0].read<0||!Number.isSafeInteger(rows[0].validLines)||rows[0].validLines<0)throw new Error('ABNORMAL_ORDER_SOURCE_UNVERIFIED');}
for(const key of ['read','validLines','beforeDedup','crossConflicts','total','added','updated','invalidated'])if(!Number.isSafeInteger(value.metrics?.[key])||value.metrics[key]<0)throw new Error('ABNORMAL_ORDER_METRICS_INVALID');
return [{json:value}];
